use std::slice;
#[no_mangle]
pub extern "C" fn print_amatrix_in_spiral_order(v:*const i64,n:usize)->i64{if v.is_null()||n<3||n>66{return -1}let a=unsafe{slice::from_raw_parts(v,n)};if !(1..=8).contains(&a[0])||!(1..=8).contains(&a[1])||n!=2+a[0] as usize*a[1] as usize||a[2..].iter().any(|x|*x<i32::MIN as i64||*x>i32::MAX as i64){return -1}let(rows,cols)=(a[0] as usize,a[1] as usize);let(mut t,mut b,mut l,mut r)=(0,rows-1,0,cols-1);let mut h=2166136261u32;let mut feed=|x:i64|{let u=x as i32 as u32;for s in (0..32).step_by(8){h=(h^((u>>s)&255)).wrapping_mul(16777619);}};while t<=b&&l<=r{for c in l..=r{feed(a[2+t*cols+c]);}t+=1;for y in t..=b{feed(a[2+y*cols+r]);}if r==0{break}r-=1;if t<=b{for c in (l..=r).rev(){feed(a[2+b*cols+c]);}if b==0{break}b-=1;}if l<=r{for y in (t..=b).rev(){feed(a[2+y*cols+l]);}l+=1;}}h as i64}
